/*
 * guest_rt.h -- runtime for code generated by tools/hybridize (docs/hybridize.md).
 *
 * Native C++ works on guest objects in place through generated view structs
 * (namespace gv). This header provides what the generated bodies call:
 *   cjg::h<T>(va) / cjg::to_guest(p)     guest VA <-> host view pointer (checked)
 *   cjg::up<B>(p, off)                   explicit derived->base adjust (MSVC layout)
 *   cjg::call_this/call_cdecl/call_std   call a recompiled function by VA with
 *                                        guest-ABI argument setup on the guest stack
 *   cjg::vcall<R>(obj, vfoff, slot,...)  guest vtable dispatch
 *   cjg::ref(x) / cjg::byval(x)          by-reference / by-value guest arguments
 *   cjg::g<T>(va)                        a global at its guest VA
 * The guest-register side is in guest_rt.c (it needs recomp_types.h, which is C).
 */
#pragma once
#include <cstdint>
#include <cstddef>
#include <cstring>
#include <type_traits>
#include "hybrid/guest.h"

/* GuestPtr<void>: VA only (guest.h's primary template needs a complete T&). */
template <> struct GuestPtr<void> {
    uint32_t va;
    void *get() const { return guest_to_host<void>(va); }
    explicit operator bool() const { return va != 0; }
    operator void *() const { return get(); }
    GuestPtr &operator=(const void *p) { va = host_to_guest(p); return *this; }   // const void* also takes void* and 0/nullptr
};

extern "C" {
void cjg_nat_enter(uint32_t va);         /* adapter: this native (cjn_) function is now active (blame attribution) */
void cjg_nat_leave(void);
uint32_t cjg_nat_cur(void);              /* innermost active native function, 0 if none */
uint32_t cjg_esp(void);
uint32_t cjg_ecx(void);
void cjg_set_esp(uint32_t);
void cjg_push_reg(int r);                /* 0 eax 1 ecx 2 edx 3 ebx 4 esp 5 ebp 6 esi 7 edi */
void cjg_set_eax(uint32_t);
void cjg_set_edx(uint32_t);
uint32_t cjg_eax(void);
void cjg_set_al(uint32_t in, uint32_t v);
void cjg_set_ax(uint32_t in, uint32_t v);
void cjg_fp_push(double);
uint32_t cjg_call_raw(uint32_t va, uint32_t ecx, const uint32_t *words, int n, int callee_pops,
                      uint32_t *edx_out, double *fp_out, int want_fp, uint32_t ret_va, uint32_t depth, int ret_pop);
void cjg_ctx_enter(uint32_t esp_in, const uint32_t *saves, int n, const uint32_t *regs, int nregs);   /* adapter: original frame context */
void cjg_ctx_leave(void);
void cjg_area_set(uint32_t lo, uint32_t size);   /* adapter: the original's local area (hybridize.py orig_frame) */
uint32_t cjg_area_take(uint32_t *size);          /* body Frame: take it (once) */
void cjg_escape(const void *p);          /* host pointer would reach guest memory: abort */
}

namespace cjg {

/* A call site: the callee VA and the return VA the ORIGINAL pushes at the matching call
 * instruction (hybridize.py orig_sites; 0 = unknown, CJG_RET_VA is pushed). The return
 * address stays on the guest stack as residue that later code reads (docs/promote.md). */
struct Site { uint32_t va, ret, depth; int pop;   /* pop: bytes the callee's ret pops (hybridize.py callee_pop), -1 = unknown */
    Site(uint32_t v, uint32_t r = 0, uint32_t d = 0, int p = -1) : va(v), ret(r), depth(d), pop(p) {} };
struct VSlot { int slot; uint32_t ret, depth; VSlot(int s, uint32_t r = 0, uint32_t d = 0) : slot(s), ret(r), depth(d) {} };

template <class T> inline T *h(uint32_t va) { return guest_to_host<T>(va); }

inline uint32_t to_guest(const void *p)
{
    if (!p) return 0;
    uintptr_t d = (uintptr_t)p - (uintptr_t)g_xbox_mem_offset;
    if (d >> 32) cjg_escape(p);
    return (uint32_t)d;
}
template <class T> inline uint32_t to_guest(const GuestPtr<T> &p) { return p.va; }

inline uint32_t rd32(uint32_t va) { uint32_t v; std::memcpy(&v, h<char>(va), 4); return v; }
template <class T> inline void rdv(uint32_t va, T *out) { std::memcpy(out, h<char>(va), sizeof(T)); }

/* explicit pointer cast: the operand is a host pointer or a GuestPtr<>; off is the MSVC base offset
 * adjustment of a derived/base record cast (0 for everything else). Null stays null. */
template <class P, class S> inline P pcast(S *p, int off) { return p ? (P)((char *)p + off) : (P) nullptr; }
template <class P, class S> inline P pcast(const GuestPtr<S> &p, int off) { return pcast<P>(p.get(), off); }

/* const method on a const object: the generated self parameter is not const-qualified */
template <class T> inline T *unconst(const T *p) { return const_cast<T *>(p); }

template <class B, class D> inline B *up(D *p, int off) { return p ? (B *)((char *)p + off) : nullptr; }
template <class B, class D> inline B *up(const GuestPtr<D> &p, int off) { return up<B>(p.get(), off); }

template <class T> inline T *g(uint32_t va) { return h<T>(va); }

/* ---- argument marshalling: each argument becomes 1..n 32-bit stack words */
struct Ref { uint32_t va; };
template <class T> inline Ref ref(T &x) { return Ref{to_guest(&x)}; }
template <class T> struct ByVal { const T *p; };
template <class T> inline ByVal<T> byval(const T &x) { return ByVal<T>{&x}; }

struct Words {
    uint32_t w[64];
    int n = 0;
    void put(uint32_t v) { w[n++] = v; }
};
template <class T> inline void put(Words &W, const T &v)
{
    if constexpr (std::is_pointer_v<T>) W.put(to_guest(v));
    else if constexpr (std::is_same_v<T, float>) { uint32_t u; std::memcpy(&u, &v, 4); W.put(u); }
    else if constexpr (std::is_same_v<T, double>) { uint32_t u[2]; std::memcpy(u, &v, 8); W.put(u[0]); W.put(u[1]); }
    else if constexpr (std::is_integral_v<T> && sizeof(T) == 8) { W.put((uint32_t)v); W.put((uint32_t)((uint64_t)v >> 32)); }
    else if constexpr (std::is_integral_v<T> || std::is_enum_v<T>) W.put((uint32_t)(int32_t)v);
    else static_assert(sizeof(T) == 0, "unsupported guest argument type");
}
inline void put(Words &W, const Ref &r) { W.put(r.va); }
inline void put(Words &W, decltype(nullptr)) { W.put(0); }
template <class T> inline void put(Words &W, const GuestPtr<T> &p) { W.put(p.va); }
template <class T> inline void put(Words &W, const ByVal<T> &b)
{
    uint32_t tmp[(sizeof(T) + 3) / 4] = {};
    std::memcpy(tmp, b.p, sizeof(T));
    for (uint32_t x : tmp) W.put(x);
}

template <class R> inline R ret(uint32_t eax, uint32_t edx, double fp)
{
    if constexpr (std::is_void_v<R>) return;
    else if constexpr (std::is_pointer_v<R>) return h<std::remove_pointer_t<R>>(eax);
    else if constexpr (std::is_reference_v<R>) return *h<std::remove_reference_t<R>>(eax);
    else if constexpr (std::is_floating_point_v<R>) return (R)fp;
    else if constexpr (std::is_same_v<R, bool>) return (eax & 0xFF) != 0;
    else if constexpr (std::is_class_v<R>) {
        /* a UDT of size 1/2/4/8 that a free function returns in eax (edx:eax) */
        static_assert(sizeof(R) == 1 || sizeof(R) == 2 || sizeof(R) == 4 || sizeof(R) == 8, "UDT return not in registers");
        uint64_t v = ((uint64_t)edx << 32) | eax; R r; std::memcpy((void *)&r, &v, sizeof(R)); return r;
    }
    else if constexpr (sizeof(R) == 8) return (R)(((uint64_t)edx << 32) | eax);
    else return (R)eax;
}

template <class R> inline R call(Site s, uint32_t ecx, int callee_pops, const Words &W)
{
    uint32_t edx = 0; double fp = 0;
    uint32_t eax = cjg_call_raw(s.va, ecx, W.w, W.n, callee_pops, &edx, &fp, std::is_floating_point_v<R>, s.ret, s.depth, s.pop);
    return ret<R>(eax, edx, fp);
}

template <class R, class T, class... A> inline R call_this(Site va, T obj, const A &...a)
{
    Words W; (put(W, a), ...);
    return call<R>(va, to_guest(obj), 1, W);
}
template <class R, class... A> inline R call_cdecl(Site va, const A &...a)
{
    Words W; (put(W, a), ...);
    return call<R>(va, 0, 0, W);
}
template <class R, class... A> inline R call_std(Site va, const A &...a)
{
    Words W; (put(W, a), ...);
    return call<R>(va, 0, 1, W);
}
/* MSVC virtual call: this = the subobject holding the vfptr; slot from the guest vftable. */
template <class R, class T, class... A> inline R vcall(T obj, int vfoff, VSlot slot, const A &...a)
{
    uint32_t self = to_guest(obj) + (uint32_t)vfoff;
    uint32_t fn = rd32(rd32(self) + 4u * (uint32_t)slot.slot);
    Words W; (put(W, a), ...);
    return call<R>(Site(fn, slot.ret, slot.depth), self, 1, W);
}

/* ---- sret (gap 3): MSVC passes the return slot as the first stack word (after ecx=this
 * for __thiscall); the callee fills it, returns its address in eax and pops it.  The slot
 * is a guest-frame address (Frame::at), so the callee writes guest memory. */
template <class R, class T, class... A> inline R &call_this_sret(R *slot, Site va, T obj, const A &...a)
{
    Words W; W.put(to_guest(slot)); (put(W, a), ...);
    call<uint32_t>(va, to_guest(obj), 1, W);
    return *slot;
}
template <class R, class... A> inline R &call_cdecl_sret(R *slot, Site va, const A &...a)
{
    Words W; W.put(to_guest(slot)); (put(W, a), ...);
    call<uint32_t>(va, 0, 0, W);
    return *slot;
}
template <class R, class T, class... A> inline R &vcall_sret(R *slot, T obj, int vfoff, VSlot slot_ix, const A &...a)
{
    uint32_t self = to_guest(obj) + (uint32_t)vfoff;
    uint32_t fn = rd32(rd32(self) + 4u * (uint32_t)slot_ix.slot);
    Words W; W.put(to_guest(slot)); (put(W, a), ...);
    call<uint32_t>(Site(fn, slot_ix.ret, slot_ix.depth), self, 1, W);
    return *slot;
}

/* ---- guest frame (gap 1): objects whose address can reach guest code live on the
 * guest stack.  The prologue moves g_esp down by the frame size (aligned); the
 * destructor restores it, so every return path releases the frame.  Guest calls made
 * from the body push below the frame. */
struct Frame {
    uint32_t old, base;
    Frame(uint32_t size, uint32_t align)
    {
        old = cjg_esp();
        base = (old - size) & ~(align - 1u);
        cjg_set_esp(base);
    }
    /* swap target body: if the adapter reserved the original's whole frame and the original's
     * local area can hold this frame, the locals live there (as in the original) and esp stays
     * where the original has it at its call sites. Otherwise the frame goes below, as above. */
    struct Area {};
    Frame(uint32_t size, uint32_t align, Area)
    {
        old = cjg_esp();
        uint32_t asz = 0, lo = cjg_area_take(&asz);
        if (lo && size <= asz) {
            uint32_t b = (lo + asz - size) & ~(align - 1u);     /* top of the area (next to the saved words) */
            if (b >= lo) { base = b; return; }
        }
        base = (old - size) & ~(align - 1u);
        cjg_set_esp(base);
    }
    ~Frame() { cjg_set_esp(old); }
    Frame(const Frame &) = delete;
    template <class T> T *at(uint32_t off) const { return h<T>(base + off); }
};
/* run f at scope exit (destructors of guest-frame locals, in reverse declaration order) */
template <class F> struct Defer { F f; ~Defer() { f(); } };
template <class F> inline Defer<F> defer(F f) { return Defer<F>{f}; }
/* copy a prvalue into a guest-frame slot so its address can be passed to guest code */
template <class T, class U> inline T &spill(T *slot, const U &v) { std::memcpy((void *)slot, (const void *)&v, sizeof(T)); return *slot; }

/* host libc on host pointers into guest memory */
inline void *h_memcpy(void *d, const void *s, uint32_t n) { return std::memcpy(d, s, n); }
inline void *h_memset(void *d, int c, uint32_t n) { return std::memset(d, c, n); }
inline int h_strcmp(const char *a, const char *b) { return std::strcmp(a, b); }
inline uint32_t h_strlen(const char *a) { return (uint32_t)std::strlen(a); }

}  // namespace cjg

namespace cjg {
template <class T, class U> inline T &assign(T *dst, const U &src) { *dst = src; return *dst; }
template <class T> inline T &assign(const GuestPtr<T> &dst, const T &src) { *dst.get() = src; return *dst.get(); }
}
